mapper.select:
SELECT d.cf_qty
FROM supplier_billing_request_detail d
JOIN supplier_billing_request h ON h.id = d.billing_id
WHERE h.status        = 'RELEASED'
  AND h.store         = #{store,jdbcType=VARCHAR}
  AND h.supplier_code = #{supplierCode,jdbcType=VARCHAR}
  AND d.item_code     = #{itemCode,jdbcType=VARCHAR}
ORDER BY h.released_at DESC
LIMIT 1
